use std::sync::{Arc, Mutex};
use std::thread;

fn w2() {
    let local: i32 = 1;
    let _ = local;
}

fn w1(m: Arc<Mutex<i32>>) {
    let mut guard = m.lock().unwrap();
    w2();
    let tmp = *guard;
    let tmp2 = tmp + 1;
    *guard = tmp2;
    drop(guard);
}

fn main() {
    let m = Arc::new(Mutex::new(0));
    let m1 = Arc::clone(&m);
    let m2 = Arc::clone(&m);
    let t1 = thread::spawn(move || w1(m1));
    let t2 = thread::spawn(move || w1(m2));
    t1.join().unwrap();
    t2.join().unwrap();
    let acc = *m.lock().unwrap();
    println!("DONE done={}", acc);
}
