    w2();
    let tmp = *guard;
    let tmp2 = tmp + 1;
    *guard = tmp2;
    drop(guard);
}

fn main() {
    let m = Arc::new(Mutex::new(0));

    let m1 = Arc::clone(&m);
    let h1 = thread::spawn(move || {
        w1(m1);
    });

    let m2 = Arc::clone(&m);
    let h2 = thread::spawn(move || {
        w1(m2);
    });

    h1.join().unwrap();
    h2.join().unwrap();

    let acc = *m.lock().unwrap();
    println!("DONE done={}", acc);
}
